from pathlib import Path
import json,base64,subprocess,hashlib
r=Path('/srv/android/asus-camera-property-map-review-20261106')
files={'src/Android.bp.snippet': '', 'src/BINDING.md': '', 'src/legacy_property_map.h': '', 'src/legacy_property_map.cpp': '', 'src/exports.map': '', 'src/import-renames.txt': '', 'tests/behavior.cpp': '', 'tests/allocator.cpp': '', 'tests/host_include/log/log.h': '', 'backend/VectorImpl.cpp': '', 'backend/String8.cpp': '', 'backend/SharedBuffer.cpp': '', 'backend/SharedBuffer.h': '', 'backend/Unicode.cpp': '', 'include/utils/SortedVector.h': '', 'include/utils/VectorImpl.h': '', 'include/utils/Errors.h': '', 'include/utils/TypeHelpers.h': '', 'include/utils/Unicode.h': '', 'include/utils/AllocatorTracker.h': '', 'include/utils/KeyedVector.h': '', 'include/utils/Compat.h': '', 'include/utils/String8.h': '', 'include/utils/Vector.h': '', 'tests/adversarial.cpp': ''}
for n,b in files.items():
 p=r/n;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(base64.b64decode(b))
commands=[]
def run(a):
 p=subprocess.run(list(map(str,a)),cwd=r,capture_output=True,text=True,timeout=45)
 commands.append({'argv':list(map(str,a)),'rc':p.returncode,'stdout':p.stdout,'stderr':p.stderr})
 (r/'host-review-commands.json').write_text(json.dumps(commands,indent=2))
 print('RC',p.returncode,p.stdout,p.stderr);assert p.returncode==0
run(['/usr/bin/g++','--version'])
flags=['-std=c++20','-O1','-g','-fno-exceptions','-ffunction-sections','-fdata-sections','-fno-strict-aliasing','-DHOST_OWNERSHIP_TEST','-Wno-attributes','-fsanitize=undefined','-fno-sanitize-recover=all','-I'+str(r/'tests/host_include'),'-I'+str(r/'src'),'-I'+str(r/'include')]
for name in ['behavior','adversarial']:
 run(['/usr/bin/g++',*flags,r/'src/legacy_property_map.cpp',r/('tests/'+name+'.cpp'),r/'tests/allocator.cpp',*[r/('backend/'+x+'.cpp') for x in ['VectorImpl','String8','SharedBuffer']],'-Wl,--gc-sections','-Wl,--wrap=malloc,--wrap=realloc,--wrap=free','-o',r/name])
 run([r/name])
print('COMMANDS_JSON '+json.dumps(commands))
size=sum(p.stat().st_size for p in r.rglob('*') if p.is_file());assert size<=32*1024**2
print('BUDGET',json.dumps({'scratch_bytes':size,'limit_bytes':32*1024**2,'cpu':list(os.sched_getaffinity(0)),'address_space':resource.getrlimit(resource.RLIMIT_AS),'cpu_seconds':resource.getrlimit(resource.RLIMIT_CPU),'per_command_wall_seconds':45,'outer_ssh_wall_seconds':110}))
